/** Опис тайтла мовою інтерфейсу; undefined, якщо власного опису немає. */
export function overviewFor(titleUk: string, lang: Lang): string | undefined {
  const o = OVERVIEWS[titleUk]
  return o ? (lang === 'uk' ? o[0] : o[1]) : undefined
}
